t:view.t:template:
var oLog = document.createElement('div');
oLog.className = 'gl-unit-log';
var aTests = this.model.getTests();
for (var i = 0; i < aTests.length; i++) {
	oLog.appendChild(new gl.unit.TestView(aTests[i]).getHTML(document));
}

var oCompleted = document.createElement('div');
var sCompleted = this.model.errors ? 'Unit tests completed with ' + this.model.errors + ' errors.' : 'Unit tests completed.';
oCompleted.appendChild(document.createTextNode(sCompleted));
oLog.appendChild(oCompleted);
var oTime = document.createElement('div');
oTime.appendChild(document.createTextNode('Time taken: ' + this.model.getTime() + 'ms'));
oLog.appendChild(oTime);
return oLog;

var oMessage = document.createElement('div');
oMessage.className = 'gl-unit-logmessage';
oMessage.appendChild(document.createTextNode(this.model.toString()));
if (!this.model.hasCompleted()) {
	oMessage.className += ' gl-notcompleted';
}
if (this.model.getError()) {
	oMessage.className += ' gl-error';
	oMessage.appendChild(document.createTextNode(' — Error: ' + (this.model.getError().message || this.model.getError())));
}
if (this.model.hasCompleted() && this.model.getTime() > 8) {
	oMessage.appendChild(document.createTextNode(' — time taken: ' + this.model.getTime() + 'ms'));
}
return oMessage;

t:view.t:resource:
.gl-window {
	position: absolute;
	max-width: 600px;
	top: 10px;
	right: 10px;
	padding: 5px;
	color: black;
	background-color: #ddf;
	font-family: Arial, sans-serif;
	font-size: smaller;
	opacity: 0.8;
	border-radius: 5px;
	-moz-border-radius: 5px;
	-webkit-border-radius: 5px;
}
.gl-window h2 {
	margin: -5px -5px 5px -5px;
	padding: 5px;
	background-color: #ccf;
	border-radius: 5px 5px 0 0;
	border-top-left-radius: 5px;
	border-top-right-radius: 5px;
	-moz-border-radius-topleft: 5px;
	-moz-border-radius-topright: 5px;
	-webkit-border-top-left-radius: 5px;
	-webkit-border-top-right-radius: 5px;
}
.gl-window h2 button {
	float: right;
}
.gl-window-minimized .gl-window-body {
	display: none;
}

t:view.t:template:
var oWindow = document.createElement('div');
oWindow.className = 'gl-window' + (this.model.isMinimized() ? ' gl-window-minimized' : '');
var oTitle = document.createElement('h2');
oTitle.appendChild(document.createTextNode(this.model.getTitle()));
var oButton = document.createElement('button');
try {
	oButton.type = 'button';
} catch(e) {
	oButton = document.createElement('<button type="button">');	// IE6/7/8...
}
oButton.appendChild(document.createTextNode(this.model.isMinimized() ? '+' : '-'));
oTitle.appendChild(oButton);
oWindow.appendChild(oTitle);

var oBody = document.createElement('div');
oBody.className = 'gl-window-body';
var aContents = this.model.getBodyContents();
for (var i = 0; i < aContents.length; i++) {
	oBody.appendChild(new gl.unit.TestSuiteView(aContents[i]).getHTML(document));
}
oWindow.appendChild(oBody);
return oWindow;
